# Implementing the required library functions based on the guide
def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, out) in enumerate(zip(inputs, outputs)):
        if inp != out:
            changed.append((i, inp, out))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit from s_in to s_out."""
    # Simple approach: find first difference and determine what needs changing
    min_len = min(len(s_in), len(s_out))

    # Find first position where strings differ
    pos = 0
    while pos < min_len and s_in[pos] == s_out[pos]:
        pos += 1

    # If we've reached end of one string, the rest is insertion/deletion
    if pos >= len(s_in) or pos >= len(s_out):
        # Check if one is prefix of other
        if len(s_in) > len(s_out):
            return (s_in[pos:], "", pos)  # deletion
        else:
            return ("", s_out[pos:], pos)  # insertion

    # Find what needs to be replaced
    old_sub = s_in[pos]
    new_sub = s_out[pos]

    # Look for longer matching patterns
    # Try to extend the pattern as much as possible
    for length in range(min(3, len(s_in)-pos), 0, -1):
        if pos + length <= len(s_in) and pos + length <= len(s_out):
            old_pattern = s_in[pos:pos+length]
            new_pattern = s_out[pos:pos+length]
            if old_pattern == new_pattern:
                continue  # Already matches

            # Check if this pattern exists in the string
            if s_in[pos:pos+length] == old_pattern:
                old_sub = old_pattern
                new_sub = new_pattern
                break

    return (old_sub, new_sub, pos)

def propose_rule_candidates(s_in, s_out):
    """Generate candidate rules from a changed pair."""
    # Find minimal edit
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)

    # Return specific to general candidates
    candidates = []

    # Most specific: exact match of minimal edit
    if old_sub and new_sub:
        candidates.append((old_sub, new_sub))
    elif old_sub and not new_sub:
        candidates.append((old_sub, ""))
    elif not old_sub and new_sub:
        candidates.append(("", new_sub))

    # Generalize to single character if possible
    if len(old_sub) > 1:
        for i in range(len(old_sub)):
            if old_sub[i:i+1] != new_sub[i:i+1] if len(new_sub) > i else True:
                candidates.append((old_sub[i:i+1], new_sub[i:i+1] if len(new_sub) > i else ""))

    # Add a generic fallback
    candidates.append((old_sub, new_sub))

    return candidates

def apply_rules(strings, rules):
    """Apply a sequence of rules to strings."""
    result = []
    for s in strings:
        new_s = s
        for pattern, replacement in rules:
            new_s = new_s.replace(pattern, replacement)
        result.append(new_s)
    return result

def score_rules(inputs, outputs, rules):
    """Score how well rules perform on the input/output set."""
    predictions = apply_rules(inputs, rules)
    correct = sum(1 for pred, true in zip(predictions, outputs) if pred == true)
    return correct / len(inputs)

def find_over_applications(inputs, outputs, rules):
    """Find cases where rules modify strings that should remain unchanged."""
    predictions = apply_rules(inputs, rules)
    over_apps = []
    for i, (inp, pred, true) in enumerate(zip(inputs, predictions, outputs)):
        if pred != true and inp == true:
            over_apps.append((i, inp, pred))
    return over_apps

def simulate_rule_chain(s, rules):
    """Show step-by-step application of rules."""
    trace = []
    current = s
    for pattern, replacement in rules:
        prev = current
        current = current.replace(pattern, replacement)
        trace.append({
            'pattern': pattern,
            'replacement': replacement,
            'before': prev,
            'after': current
        })
    return trace

