print("\nAnalyzing each changed pair:")
for idx, inp, out in changed:
    print(f"\nPair {idx}: '{inp}' -> '{out}'")

    # Find minimal edit
    old_sub, new_sub, pos = find_minimal_edit(inp, out)
    print(f"  Minimal edit: '{old_sub}' -> '{new_sub}' at position {pos}")

    # Propose candidates
    candidates = propose_rule_candidates(inp, out)
    print(f"  Candidates: {candidates}")

